/* Real isolated PostgreSQL, no application bootstrap, no SMTP and no external DB URL.
 * Requires a separately installed embedded-postgres module; see docs/waitlist.md.
 * Temporary fixture files are generated by the test, not deployment artifacts.
 */
const { test } = require('node:test');
const assert = require('node:assert/strict');
const fs = require('node:fs/promises');
const os = require('node:os');
const path = require('node:path');
const net = require('node:net');
const { pathToFileURL } = require('node:url');
const { randomUUID } = require('node:crypto');
const { execFileSync } = require('node:child_process');
const { PrismaClient } = require('@prisma/client');
const { WaitlistService } = require('../dist/waitlist/waitlist.service');
const { RestockDeliveryError } = require('../dist/email/restock-delivery.error');
const { ProductService } = require('../dist/products/product.service');
const { AdminInventoryService } = require('../dist/admin/inventory/admin-inventory.service');

test('Waitlist: PostgreSQL transaccional aislado + SMTP falso', { timeout: 180000 }, async t => {
  assert.ok(process.env.WAITLIST_TEST_PG_MODULE, 'Set WAITLIST_TEST_PG_MODULE to embedded-postgres/dist/index.js (local testing only).');
  const { default: EmbeddedPostgres } = await import(pathToFileURL(process.env.WAITLIST_TEST_PG_MODULE).href);
  const dir = await fs.mkdtemp(path.join(os.tmpdir(), 'cronox-waitlist-db-'));
  const probe = net.createServer();
  await new Promise(resolve => probe.listen(0, '127.0.0.1', resolve));
  const port = probe.address().port;
  await new Promise(resolve => probe.close(resolve));
  const password = randomUUID();
  const server = new EmbeddedPostgres({ databaseDir: path.join(dir, 'pg'), port, user: 'waitlist_test', password,
    persistent: true, createPostgresUser: false, postgresFlags: ['-h', '127.0.0.1'], onLog: () => {}, onError: () => {} });
  let db, sql;
  try {
    await server.initialise(); await server.start();
    await server.createDatabase('waitlist_test');
    const url = `postgresql://waitlist_test:${password}@127.0.0.1:${port}/waitlist_test`;
    sql = server.getPgClient('waitlist_test', '127.0.0.1'); await sql.connect();
    await sql.query('CREATE EXTENSION IF NOT EXISTS pg_trgm');
    // Base schema only, then the exact additive migration under review.
    const schema = (await fs.readFile(path.join(__dirname, '../prisma/schema.prisma'), 'utf8'))
      .replace(/^.*restockRequests\s+RestockRequest\[\].*\r?\n/gm, '')
      .replace(/model RestockRequest \{[\s\S]*?\n\}/, '');
    const schemaFile = path.join(dir, 'schema.prisma'); await fs.writeFile(schemaFile, schema);
    execFileSync(process.execPath, [require.resolve('prisma/build/index.js'), 'db', 'push', '--schema', schemaFile, '--skip-generate'],
      { cwd: path.join(__dirname, '..'), env: { ...process.env, DATABASE_URL: url }, stdio: 'pipe', windowsHide: true });
    await sql.query(await fs.readFile(path.join(__dirname, '../prisma/migrations/20260925120000_restock_waitlist/migration.sql'), 'utf8'));
    db = new PrismaClient({ datasources: { db: { url } } });
    await db.$connect();
    // Exercise the production default; SMTP is still replaced by the fake below.
    delete process.env.WAITLIST_EMAIL_WORKER_ENABLED;
    process.env.FRONTEND_URL = 'https://store.example.test';
    const sent = []; let enabled = true, failure = null;
    const mail = { isRestockSenderConfigured: () => enabled, sendRestock: async (...args) => { if (failure) throw failure; sent.push(args); } };
    const service = new WaitlistService(db, mail);
    const worker2 = new WaitlistService(db, mail);
    const user = await db.user.create({ data: { email: 'first@example.test' } });
    const other = await db.user.create({ data: { email: 'second@example.test' } });
    const product = await db.product.create({ data: { slug: 'test-tee', name: 'Test <TEE>', price: 1000,
      variants: { create: [{ size: 'M', sku: 'TEST-M', stockQty: 0 }, { size: 'L', sku: 'TEST-L', stockQty: 0 }] },
      images: { create: { url: 'https://img.example.test/original', isPrimary: true, variants: { small: { url: 'https://img.example.test/small.webp' } } } },
    }, include: { variants: true } });
    const m = product.variants.find(v => v.size === 'M').id, l = product.variants.find(v => v.size === 'L').id;
    const status = id => db.restockRequest.findUnique({ where: { id } });
    const stock = (id, n) => db.productVariant.update({ where: { id }, data: { stockQty: n } });
    const due = () => db.restockRequest.updateMany({ where: { status: 'QUEUED' }, data: { readyAt: new Date(0) } });
    let requestId;
    await t.test('whole product sold out, concurrent duplicate joins have one active identity', async () => {
      const joins = await Promise.all(Array.from({ length: 8 }, () => service.join(user.id, m)));
      assert.equal(new Set(joins.map(j => j.subscription.id)).size, 1);
      requestId = joins[0].subscription.id;
      assert.equal(await db.restockRequest.count(), 1);
      // Constraint also protects writers which do not use the service locks.
      await assert.rejects(db.restockRequest.create({ data: { userId: user.id, variantId: m } }), e => e.code === 'P2002');
    });
    await t.test('ownership: another customer cannot see/cancel this request', async () => {
      assert.equal((await service.state(other.id, m)).subscription, null);
      await service.cancel(other.id, m);
      assert.equal((await status(requestId)).status, 'WAITING');
    });
    await t.test('other size, rollback and worker restart do not invent an event', async () => {
      await stock(l, 3); await service.tick(); assert.equal(sent.length, 0);
      await assert.rejects(db.$transaction(async tx => {
        await tx.productVariant.update({ where: { id: m }, data: { stockQty: 4 } });
        throw new Error('rollback');
      }));
      await worker2.tick(); assert.equal((await status(requestId)).status, 'WAITING');
      assert.equal(sent.length, 0);
    });
    await t.test('committed exact restock, five-minute debounce, positive-to-positive no requeue', async () => {
      await stock(m, 1); const queued = await status(requestId);
      assert.equal(queued.status, 'QUEUED'); assert.ok(queued.readyAt.getTime() > Date.now() + 290000);
      await stock(m, 4); assert.equal((await status(requestId)).readyAt.getTime(), queued.readyAt.getTime());
      await service.tick(); assert.equal(sent.length, 0);
    });
    await t.test('disabled email preserves the queue, then concurrent workers accept once', async () => {
      await due(); enabled = false; await service.tick(); assert.equal(sent.length, 0);
      assert.equal((await status(requestId)).attempts, 0);
      enabled = true; await Promise.all([service.tick(), worker2.tick()]);
      assert.equal(sent.length, 1); assert.equal((await status(requestId)).status, 'ACCEPTED');
      assert.equal(sent[0][0], user.email);
      assert.equal(sent[0][1].size, 'M'); assert.equal(sent[0][1].product, 'Test <TEE>');
      assert.equal(sent[0][1].actionUrl, 'https://store.example.test/producto/test-tee?size=M');
      assert.equal(sent[0][1].imageUrl, 'https://img.example.test/small.webp');
      await Promise.all([service.tick(), worker2.tick()]); assert.equal(sent.length, 1);
    });
    await t.test('fulfilled requests never auto-enroll; explicit later cycle and availability races', async () => {
      await assert.rejects(service.join(user.id, m), /ya está disponible/);
      await stock(m, 0); await stock(m, 1); await due(); await service.tick(); assert.equal(sent.length, 1);
      await stock(m, 0); requestId = (await service.join(user.id, m)).subscription.id;
      await stock(m, 1); await stock(m, 0); await due(); await service.tick();
      assert.equal((await status(requestId)).status, 'WAITING'); assert.equal(sent.length, 1);
    });
    await t.test('hidden/inactive variants; reactivation is a new debounced opportunity', async () => {
      await db.product.update({ where: { id: product.id }, data: { isActive: false } });
      await stock(m, 2); await due(); await service.tick(); assert.equal(sent.length, 1);
      await assert.rejects(service.join(other.id, m), /no admite avisos/);
      await db.product.update({ where: { id: product.id }, data: { isActive: true } });
      assert.equal((await status(requestId)).status, 'QUEUED');
      await db.productVariant.update({ where: { id: m }, data: { isActive: false } });
      assert.equal((await status(requestId)).status, 'WAITING');
      await db.productVariant.update({ where: { id: m }, data: { isActive: true } });
      assert.equal((await status(requestId)).status, 'QUEUED');
    });
    await t.test('cancelling queued request prevents dispatch and allows explicit new cycle', async () => {
      await service.cancel(user.id, m); await due(); await service.tick(); assert.equal(sent.length, 1);
      assert.equal((await status(requestId)).status, 'CANCELLED');
      await stock(m, 0); requestId = (await service.join(user.id, m)).subscription.id;
    });
    await t.test('safe failures retry at most three times; ambiguous failure never retries', async () => {
      failure = new RestockDeliveryError('RETRY'); await stock(m, 2);
      for (let i = 0; i < 3; i++) { await due(); await service.tick(); }
      assert.equal((await status(requestId)).status, 'FAILED'); assert.equal((await status(requestId)).attempts, 3);
      failure = null; await due(); await worker2.tick(); assert.equal(sent.length, 1);
      await service.cancel(user.id, m); await stock(m, 0); requestId = (await service.join(user.id, m)).subscription.id;
      failure = new RestockDeliveryError('UNCERTAIN'); await stock(m, 2); await due(); await service.tick();
      assert.equal((await status(requestId)).status, 'UNCERTAIN');
      failure = null; await worker2.tick(); assert.equal(sent.length, 1);
    });
    await t.test('restart preserves uncertain claims instead of sending again', async () => {
      await service.cancel(user.id, m); await stock(m, 0); requestId = (await service.join(user.id, m)).subscription.id;
      await db.restockRequest.update({ where: { id: requestId }, data: { status: 'PROCESSING', claimedAt: new Date(0), claimToken: 'interrupted' } });
      await worker2.tick(); assert.equal((await status(requestId)).status, 'UNCERTAIN'); assert.equal(sent.length, 1);
    });
    await t.test('admin counts distinct people across sizes, filters and excludes cancelled/fulfilled', async () => {
      await stock(l, 0); await service.join(user.id, l); await service.join(other.id, l);
      const report = await service.report({ page: 1 });
      assert.equal(report.workerEnabled, true);
      assert.equal(report.total, 2); assert.equal(report.rows[0].id, l); assert.equal(report.rows[0].demand, 2);
      assert.equal(report.rows[0].productPeople, 2); // Same user waits for M and L, not three people.
      const filtered = await service.report({ page: 1, size: 'M', status: 'UNCERTAIN', search: 'TEST-M' });
      assert.equal(filtered.rows.length, 1); assert.equal(filtered.rows[0].demand, 1);
      assert.equal(filtered.rows[0].accepted, 1); assert.equal(filtered.rows[0].cancelled, 3);
      assert.equal((await service.report({ page: 1, search: "' OR 1=1 --" })).total, 0);
    });
    await t.test('all waiting customers notified even if only one unit is restocked', async () => {
      await stock(l, 1); await due(); await Promise.all([service.tick(), worker2.tick()]);
      assert.equal(sent.length, 3); assert.deepEqual(sent.slice(1).map(x => x[0]).sort(), [user.email, other.email].sort());
    });
    await t.test('variant identity edits cancel unfulfilled requests; deleted accounts cascade', async () => {
      await db.productVariant.update({ where: { id: m }, data: { size: 'S' } });
      assert.equal((await status(requestId)).status, 'CANCELLED');
      await stock(l, 0); const toDelete = await db.user.create({ data: { email: 'deleted@example.test' } });
      await service.join(toDelete.id, l); await db.user.delete({ where: { id: toDelete.id } });
      assert.equal(await db.restockRequest.count({ where: { userId: toDelete.id } }), 0);
    });
    await t.test('RLS enabled and no historical scan in the migration', async () => {
      const rows = await sql.query("SELECT relrowsecurity FROM pg_class WHERE relname='RestockRequest'");
      assert.equal(rows.rows[0].relrowsecurity, true);
    });
    await t.test('real inventory service: bulk rollback, committed save and manual adjustment trigger the same queue', async () => {
      const inventory = new AdminInventoryService(db), products = new ProductService(db);
      await stock(l, 0); const joined = await service.join(user.id, l);
      await assert.rejects(inventory.update(product.id, { updates: [
        { variantId: m, expectedStock: 0, stock: 1 }, { variantId: l, expectedStock: 99, stock: 1 },
      ] }));
      assert.equal((await status(joined.subscription.id)).status, 'WAITING');
      await inventory.update(product.id, { updates: [{ variantId: l, expectedStock: 0, stock: 1 }] });
      assert.equal((await status(joined.subscription.id)).status, 'QUEUED');
      await products.adjustVariantStock(product.id, l, { delta: -1 });
      assert.equal((await status(joined.subscription.id)).status, 'WAITING');
      await products.adjustVariantStock(product.id, l, { delta: 1 });
      assert.equal((await status(joined.subscription.id)).status, 'QUEUED');
      await service.cancel(user.id, l);
    });
    await t.test('restock racing a join cannot leave a new WAITING request for an available variant', async () => {
      for (let i = 0; i < 5; i++) {
        await stock(l, 0);
        const [join] = await Promise.allSettled([service.join(other.id, l), stock(l, 1)]);
        if (join.status === 'fulfilled') {
          assert.equal((await status(join.value.subscription.id)).status, 'QUEUED');
          await service.cancel(other.id, l);
        } else assert.match(join.reason.message, /ya está disponible/);
      }
    });
    await t.test('a locked request is skipped by another worker without blocking or double-claiming', async () => {
      await stock(l, 0);
      const a = await service.join(user.id, l), b = await service.join(other.id, l);
      await stock(l, 1); await due();
      await sql.query('BEGIN');
      try {
        await sql.query('SELECT id FROM "RestockRequest" WHERE id=$1 FOR UPDATE', [a.subscription.id]);
        const before = sent.length;
        await worker2.tick(); assert.equal(sent.length, before + 1);
        assert.equal((await status(a.subscription.id)).status, 'QUEUED');
        assert.equal((await status(b.subscription.id)).status, 'ACCEPTED');
      } finally { await sql.query('ROLLBACK'); }
      await service.tick(); assert.equal((await status(a.subscription.id)).status, 'ACCEPTED');
    });
  } finally {
    process.env.WAITLIST_EMAIL_WORKER_ENABLED = 'false';
    if (db) await db.$disconnect(); if (sql) await sql.end();
    await server.stop();
    // persistent=true: retain ONLY this isolated temp fixture for failure inspection.
    console.log('PostgreSQL de prueba detenido. Carpeta temporal:', dir);
  }
});
